  static Background4KEntry bySlot(int index) {
    final safe = ((index % 500) + 500) % 500;
    return all500[safe];
  }

  /// تخصيص ٢٠ خلفية مختلفة لحقيبة الفردوس (٠..١٩)
  static Background4KEntry forBagItem(int idx) => bySlot(idx.clamp(0, 19));

  /// خلفيات واقعية منفصلة لبطاقات التقويم حسب كل صلاة (٢٠..٢٧)
  static Background4KEntry forCalendarPrayer(String prayerKey) {
    switch (prayerKey.toLowerCase()) {
      case 'fajr':
        return all500[20];
      case 'sunrise':
        return all500[21];
      case 'duha':
        return all500[22];
      case 'dhuhr':
        return all500[23];
      case 'asr':
        return all500[24];
      case 'maghrib':
        return all500[25];
      case 'isha':
        return all500[26];
      default:
        return all500[27];
    }
  }

  /// خلفيات واقعية منفصلة لبطاقات سجل الصلوات التاريخي (٢٨..٣٥)
  static Background4KEntry forPrayerLogKey(String prayerKey) {
    switch (prayerKey.toLowerCase()) {
      case 'fajr':
        return all500[28];
      case 'dhuhr':
        return all500[29];
      case 'asr':
        return all500[30];
      case 'maghrib':
        return all500[31];
      case 'isha':
        return all500[32];
      default:
        return all500[33];
    }
  }

